# --- SQL (100 distinct cards) ---
sql_cards = [
    ("What is the logical query execution order in SQL?", "SQL clauses evaluate in this order: FROM/JOIN, WHERE, GROUP BY, HAVING, SELECT, DISTINCT, ORDER BY, and LIMIT/OFFSET."),
    ("Why can't you use column aliases defined in SELECT inside the WHERE clause?", "WHERE executes before the SELECT clause calculates column expressions and assigns aliases, so aliases do not yet exist."),
    ("What is the fundamental difference between WHERE and HAVING?", "WHERE filters rows before aggregation occurs; HAVING filters summary groups after GROUP BY aggregation has been computed."),
    ("What happens when you use COUNT(*) vs COUNT(column)?", "COUNT(*) counts all rows including those with NULLs; COUNT(column) counts only rows where that specific column is non-NULL."),
    ("Why does SELECT * FROM orders WHERE ROW_NUMBER() <= 3 throw an error?", "Window functions evaluate in the SELECT phase, which occurs after WHERE; you must wrap them inside a subquery or CTE."),
    ("What is the difference between UNION and UNION ALL?", "UNION performs an expensive distinct sort to eliminate duplicate rows, while UNION ALL retains all rows and runs faster."),
    ("What is the difference between RANK() and DENSE_RANK()?", "RANK leaves gaps in sequence numbering when ties occur (1, 2, 2, 4); DENSE_RANK assigns consecutive numbers without gaps (1, 2, 2, 3)."),
    ("What does ROW_NUMBER() return when two rows tie on the ORDER BY column?", "It assigns unique, non-deterministic consecutive integers unless additional tie-breaker columns are added to the ORDER BY clause."),
    ("How do you find the second highest salary without using LIMIT or OFFSET?", "Use DENSE_RANK() OVER (ORDER BY salary DESC) inside a CTE and filter where rank equals 2."),
    ("What is the default window frame when ORDER BY is present in an OVER clause?", "The default frame is RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW, which can cause duplicate row values to group together."),
    ("Why should you specify ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW for running totals?", "Specifying ROWS prevents identical values from being grouped together into ties, ensuring true physical row-by-row cumulative accumulation."),
    ("How does LAST_VALUE() behave if you omit an explicit window frame?", "It evaluates only up to the CURRENT ROW by default; you must specify ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING."),
    ("What does COALESCE() do when given multiple arguments?", "It evaluates expressions from left to right and returns the first non-null value, or NULL if all arguments are null."),
    ("How does NULLIF(expression1, expression2) help prevent division-by-zero errors?", "It returns NULL if expression1 equals expression2; placing NULLIF(denominator, 0) causes division by zero to safely yield NULL."),
    ("What is the result of TRUE AND NULL, FALSE AND NULL, and NULL = NULL in SQL three-valued logic?", "TRUE AND NULL yields NULL; FALSE AND NULL yields FALSE; NULL = NULL evaluates to UNKNOWN (neither TRUE nor FALSE)."),
    ("Why does WHERE column NOT IN (1, 2, NULL) return zero rows?", "In SQL, comparing against NULL yields UNKNOWN; any row tested against NOT IN with a NULL in the list evaluates to UNKNOWN."),
    ("What is a Correlated Subquery and why can it be slow?", "A subquery that references columns from the outer query, forcing the database engine to execute it once for every outer row."),
    ("How does the EXISTS operator improve performance over IN for subqueries?", "EXISTS stops scanning the inner table as soon as the first matching row is found (short-circuit evaluation)."),
    ("What is a Common Table Expression (CTE) and when should you prefer it over subqueries?", "A CTE is a temporary named result set defined with WITH that improves query readability and allows recursive operations."),
    ("What is a Recursive CTE and what are its two required parts?", "A CTE referencing itself, consisting of an Anchor member (base query) and a Recursive member joined by UNION ALL."),
    ("What is the difference between an INNER JOIN and a LEFT JOIN?", "INNER JOIN returns only rows with matches in both tables; LEFT JOIN returns all left rows plus matching right rows or NULLs."),
    ("What occurs when a table join condition matches multiple rows in the joined table?", "Row fan-out occurs: the original row is duplicated for each matching joined row, which can inflate sum aggregations."),
    ("How do you prevent row fan-out from distorting aggregate sums after a 1-to-many join?", "Aggregate the child table to the parent key level in a CTE before joining, or use distinct key-level calculations."),
    ("What is a CROSS JOIN and what is its output row count?", "A Cartesian product joining every row of table A to every row of table B, producing rows(A) multiplied by rows(B)."),
    ("What is a SELF JOIN and when is it typically used?", "A table joined to itself using different aliases, commonly used for hierarchical data like employee-manager relationships."),
    ("What is the difference between FULL OUTER JOIN and CROSS JOIN?", "FULL OUTER JOIN matches on keys and fills non-matches with NULLs; CROSS JOIN unconditionally combines every row with every row."),
    ("How do GROUP BY 1 and ORDER BY 1 work in SQL?", "The number refers to the 1st column in the SELECT list; while convenient, using explicit column names is preferred in production."),
    ("What is the difference between NTILE(4) and quartile calculation?", "NTILE(4) divides rows into four roughly equal bucket sizes by row count, which may split identical tie values across buckets."),
    ("How do LAG() and LEAD() functions work?", "LAG accesses a column value from N rows before the current row; LEAD accesses a column value from N rows after."),
    ("How do you calculate Month-over-Month (MoM) percentage growth in SQL?", "Use LAG(revenue) OVER (ORDER BY month) to fetch previous month's revenue, then compute (revenue - prev) / NULLIF(prev, 0) * 100."),
    ("What is the difference between primary keys and unique constraints?", "A table can have only one primary key and it cannot contain NULLs; unique constraints allow NULLs and multiple per table."),
    ("What is referential integrity in relational databases?", "A rule enforced by foreign keys ensuring that a record referencing another table always points to an existing valid parent record."),
    ("What does ON DELETE CASCADE do on a foreign key?", "When a parent row is deleted, the database automatically deletes all corresponding child rows referencing that parent."),
    ("What is a B-Tree index and how does it speed up queries?", "A balanced tree structure maintaining sorted keys that allows logarithmic time lookups, range scans, and equality checks."),
    ("Why might a database optimizer perform a Sequential Scan even when an index exists?", "If the query selects a large percentage of table rows (e.g. >20%), scanning the table directly is faster than index seeks."),
    ("What is a Composite Index and what is the leftmost prefix rule?", "An index on multiple columns (A, B); it accelerates queries filtering on A, or A and B, but not B alone."),
    ("How does wrapping a column in a function like WHERE YEAR(order_date) = 2024 affect index usage?", "It makes the predicate non-sargable, preventing the optimizer from using an index on order_date; use range bounds instead."),
    ("What is a sargable query predicate?", "A search condition that can take advantage of an index (e.g. order_date >= '2024-01-01' AND order_date < '2025-01-01')."),
    ("What is the difference between Clustered and Non-Clustered indexes?", "A clustered index defines physical row storage order on disk (one per table); non-clustered indexes store pointers to table rows."),
    ("What does EXPLAIN or EXPLAIN ANALYZE do?", "EXPLAIN shows the optimizer's planned execution steps and estimated costs; ANALYZE actually executes the query and shows real times."),
    ("What is a database transaction and what does COMMIT vs ROLLBACK do?", "A transaction is a unit of work; COMMIT saves changes permanently, while ROLLBACK undoes changes back to the start."),
    ("What are ACID properties in database systems?", "Atomicity (all or nothing), Consistency (rules maintained), Isolation (independent transactions), and Durability (survives crashes)."),
    ("What are the four standard SQL transaction isolation levels?", "Read Uncommitted, Read Committed (default in many DBs), Repeatable Read, and Serializable (highest isolation)."),
    ("What is a Dirty Read in database transactions?", "When a transaction reads uncommitted data written by another concurrent transaction that might later be rolled back."),
    ("What is a Non-Repeatable Read vs a Phantom Read?", "Non-repeatable read: re-reading a row gets modified data; Phantom read: re-running a range query finds newly inserted rows."),
    ("What is a database Deadlock and how does the engine resolve it?", "Two transactions waiting for locks held by each other; the engine detects the cycle and aborts/rolls back one transaction."),
    ("What is the difference between a View and a Materialized View?", "A view executes its underlying query dynamically on every access; a materialized view stores physical precomputed results on disk."),
    ("How do you refresh a Materialized View?", "By issuing a REFRESH MATERIALIZED VIEW command manually or via scheduled background cron jobs."),
    ("What is a Stored Procedure and how does it differ from a User-Defined Function (UDF)?", "Procedures execute business logic and can commit transactions; functions must return a value and cannot modify transaction state."),
    ("What is a database Trigger and what are common pitfalls?", "Code executed automatically on INSERT/UPDATE/DELETE; pitfalls include hidden side effects, debugging difficulty, and performance overhead."),
    ("What is the difference between CHAR, VARCHAR, and TEXT data types?", "CHAR has fixed storage width with padding; VARCHAR has variable length up to a limit; TEXT holds arbitrarily large strings."),
    ("How does SQLite handle date and time values compared to PostgreSQL?", "SQLite has no dedicated datetime type; it stores dates as text, reals, or integers and uses strftime() for date math."),
    ("How do you format timestamps in SQLite using strftime?", "Use strftime('%Y-%m', date_col) for year-month extraction or strftime('%s', date_col) for Unix epoch seconds."),
    ("What does CASE WHEN syntax look like in SQL?", "CASE WHEN condition1 THEN val1 WHEN condition2 THEN val2 ELSE fallback END; evaluation stops at the first true condition."),
    ("How do you perform Conditional Aggregation in SQL?", "Use SUM(CASE WHEN status = 'Completed' THEN amount ELSE 0 END) to calculate filtered sums within a single query pass."),
    ("What is the difference between COUNT(DISTINCT customer_id) and APPROX_COUNT_DISTINCT?", "COUNT DISTINCT gives exact unique counts; approximate functions use HyperLogLog algorithms to provide 1-2% accuracy at huge speed."),
    ("What is the difference between string concatenation using || vs CONCAT()?", "The || operator in standard SQL returns NULL if any operand is NULL; CONCAT() in MySQL/Postgres ignores NULL arguments."),
    ("How do you find duplicate rows in a table using SQL?", "GROUP BY all defining columns and filter with HAVING COUNT(*) > 1."),
    ("How do you delete duplicate records while keeping the row with the lowest ID?", "Use a CTE with ROW_NUMBER() OVER (PARTITION BY unique_keys ORDER BY id) and DELETE WHERE row_num > 1."),
    ("What is the purpose of the COALESCE function in revenue calculations?", "It replaces NULL discounts or costs with 0 so arithmetic operations like revenue - COALESCE(discount, 0) do not return NULL."),
    ("What is a Cartesian Product and when is it dangerous?", "An unconstrained cross join combining all rows; dangerous on large tables because output rows explode to N * M."),
    ("How does the INTERSECT operator differ from an INNER JOIN?", "INTERSECT compares entire result sets and returns distinct matching rows; INNER JOIN combines specific columns on explicit join keys."),
    ("What does the EXCEPT (or MINUS) operator do?", "It returns distinct rows found in the first query that do not exist in the second query's result set."),
    ("What is the difference between IN and EXISTS when checking for subquery results?", "IN compares values against an enumerated list; EXISTS tests whether the subquery produces at least one row."),
    ("Why should you avoid SELECT * in production analytics queries?", "It wastes network bandwidth, breaks caching, degrades column-store performance, and causes errors if schemas change."),
    ("How do window frames with UNBOUNDED PRECEDING differ from CURRENT ROW?", "UNBOUNDED PRECEDING starts from the first row of the partition; CURRENT ROW stops at the active row being calculated."),
    ("What does PERCENT_RANK() calculate in SQL?", "It calculates relative rank as (rank - 1) / (total_rows - 1), returning values from 0.0 to 1.0."),
    ("What does CUME_DIST() calculate in SQL?", "It calculates cumulative distribution: the number of rows with values <= current row divided by total partition rows."),
    ("How do you calculate a 7-day rolling average in SQL?", "AVG(revenue) OVER (ORDER BY date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)."),
    ("What is the difference between ROWS and RANGE in a window frame specification?", "ROWS counts physical rows before/after; RANGE evaluates logical value offsets, treating duplicate values as ties."),
    ("What does the QUALIFY clause do in modern SQL dialects (e.g. Snowflake, BigQuery)?", "It filters results of window functions directly without requiring an outer wrapper subquery or CTE."),
    ("How do you pivot rows into columns in standard SQL without PIVOT syntax?", "Use conditional aggregation: MAX(CASE WHEN category = 'A' THEN sales END) GROUP BY id."),
    ("How do you unpivot columns into rows in SQL?", "Use UNION ALL to select each column alongside a literal label name, or use native UNPIVOT clauses where supported."),
    ("What is Database Normalization and what is Third Normal Form (3NF)?", "Organizing schemas to reduce redundancy; 3NF requires no transitive dependencies (non-key columns depend only on primary key)."),
    ("Why do data warehouses often prefer Denormalized schemas over 3NF?", "Denormalization reduces expensive multi-table joins, accelerating analytical query read speeds on large datasets."),
    ("What is a surrogate key vs a natural key in a data warehouse?", "A surrogate key is an internal auto-increment integer or hash; a natural key is the original business identifier from source systems."),
    ("What is the purpose of an audit table or history log in SQL?", "To record timestamps, user IDs, and before/after values for data changes to provide accountability and rollbacks."),
    ("How does TRUNCATE TABLE differ from DELETE FROM table?", "TRUNCATE drops and recreates table pages without logging row deletions, running much faster and resetting auto-increment counters."),
    ("What is the difference between DROP TABLE and TRUNCATE TABLE?", "DROP removes the table definition, schema, and data completely; TRUNCATE removes only data rows while keeping the structure."),
    ("What is the difference between a clustered database and a partitioned table?", "Clustering groups similar rows close together; partitioning splits table data into separate physical files by partition key."),
    ("What is a temporary table and when is it dropped?", "A table visible only within the active session or transaction that is automatically dropped when the session disconnects."),
    ("How do you generate a series of sequential numbers or dates in SQL?", "Use recursive CTEs, or dialect-specific generators like generate_series() in PostgreSQL or range() in BigQuery."),
    ("What is the difference between CAST and CONVERT?", "CAST is ANSI SQL standard syntax; CONVERT is dialect-specific (e.g. T-SQL) allowing custom formatting parameters for dates."),
    ("What does GROUPING SETS do in SQL?", "It allows specifying multiple GROUP BY combinations in a single query, unioning their aggregate outputs efficiently."),
    ("What does the ROLLUP operator do in a GROUP BY clause?", "It generates hierarchical subtotals and a grand total for specified columns from right to left."),
    ("What does the CUBE operator do in a GROUP BY clause?", "It generates subtotals for all possible mathematical combinations of dimensions listed in the grouping clause."),
    ("How do you handle case-insensitive string searches in SQL?", "Use LOWER(column) = 'value', or the ILIKE operator in PostgreSQL, or configure case-insensitive collations."),
    ("What is a collation in SQL?", "A set of rules determining how character string data is sorted and compared for equality across languages."),
    ("What is an upsert operation in SQL?", "An INSERT statement that updates existing records if a unique key conflict occurs (e.g. ON CONFLICT DO UPDATE)."),
    ("What does the MERGE statement do in SQL?", "It synchronizes a target table with a source table by performing INSERTs, UPDATEs, and DELETEs in a single statement."),
    ("How do you find the median value in SQL without a built-in MEDIAN() function?", "Use PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY col) or calculate the 50th percentile using window functions."),
    ("What is the difference between PERCENTILE_CONT and PERCENTILE_DISC?", "PERCENTILE_CONT interpolates continuous values; PERCENTILE_DISC returns an actual discrete value existing in the dataset."),
    ("Why should you avoid using NOT IN with nullable subquery columns?", "If any returned row in the subquery is NULL, the entire NOT IN condition evaluates to UNKNOWN, returning zero results."),
    ("How do you safely rewrite NOT IN to handle NULL values?", "Use NOT EXISTS (SELECT 1 ...) or explicitly filter out NULLs with WHERE sub_col IS NOT NULL."),
    ("What is the difference between string LENGTH() and OCTET_LENGTH()?", "LENGTH counts the number of characters; OCTET_LENGTH counts the raw number of bytes (relevant for multi-byte UTF-8)."),
    ("How do you extract query performance bottlenecks using EXPLAIN output?", "Look for high-cost nodes, Sequential Scans on large tables, Sort operations spilling to disk, and nested loop joins on large sets."),
    ("What does spilling to disk mean during a SQL query execution?", "When available working memory (work_mem) is exceeded during sorting or hash joins, forcing temporary data writes to slow disk storage."),
    ("What is the impact of using wildcards at the beginning of a LIKE pattern (%abc)?", "It prevents the database from using B-Tree indexes, forcing a full sequential scan across all table rows."),
    ("How do you enforce data integrity at the database schema level?", "Using NOT NULL constraints, UNIQUE constraints, PRIMARY KEYs, FOREIGN KEYs, and CHECK constraints (e.g. CHECK (price > 0))."),
    ("What is an isolation anomaly known as write skew?", "When concurrent transactions read overlapping data and update distinct data violating a global constraint (prevented by Serializable isolation).")
]
for i, (f, b) in enumerate(sql_cards):
    add_fc(f"fc-sql-{i+1:03d}", "sql", f, b)

